def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > opp_pressure:
                    opp_pressure = float(bid)

    if budget <= 0:
        return 0.0

    units = max(1, int(supply // WATER_REQ))
    scarcity = 1.0
    if units <= 1:
        scarcity = 1.0
    elif units == 2:
        scarcity = 0.72
    else:
        scarcity = 0.55

    danger = 0.0
    if hp <= 2:
        danger += 0.5
    elif hp <= 4:
        danger += 0.28
    if no_water_days >= 2:
        danger += 0.45
    elif no_water_days == 1:
        danger += 0.2
    if day >= 8:
        danger += 0.12

    if not alive_opponents:
        base = DAILY_SALARY * 0.28 + DAILY_SALARY * danger
        return float(max(0.0, min(budget, base)))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if units <= 1:
        target = max(DAILY_SALARY * (0.78 + danger), avg_prev + 3.0, max_prev * 0.92)
    else:
        if max_prev >= 95:
            target = DAILY_SALARY * (0.34 + 0.35 * danger)
        elif max_prev >= 70:
            target = DAILY_SALARY * (0.48 + 0.4 * danger)
        else:
            target = max(DAILY_SALARY * (0.42 + 0.45 * danger), avg_prev + 2.0)

    target *= scarcity

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.82)

    if hp <= 2 or no_water_days >= 2:
        emergency = max(DAILY_SALARY * 0.9, max_prev + 4.0)
        if units > 1:
            emergency *= 0.9
        target = max(target, emergency)

    floor_bid = 8.0 if units > 1 else 18.0
    bid = max(floor_bid, target)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    prev_bids = []
    for opp_id, opp in alive_opponents.items():
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and 'bid' in prev_trace and prev_trace['bid'] is not None:
            prev_bids.append(prev_trace['bid'])
    if prev_bids:
        max_prev_bid = max(prev_bids)
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            target_bid = min(my_status['budget'], max(DAILY_SALARY * 0.8, max_prev_bid + 1.0))
        else:
            target_bid = min(my_status['budget'], max(DAILY_SALARY * 0.5, max_prev_bid + 0.5))
    else:
        target_bid = min(my_status['budget'], DAILY_SALARY * 0.5)
    supply = day_context['supply']
    if supply < 20:
        target_bid = min(target_bid * 1.2, my_status['budget'])
    return max(0, target_bid)

def get_bid(day_context, my_status, opponents_status):
