    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 50.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 98.0
    target_bid = avg_prev * 1.05

    if day_context['supply'] < 18:
        target_bid *= 1.2

    if my_status['hp'] < 4:
        target_bid = max(target_bid, DAILY_SALARY * 0.8)

    return min(my_status['budget'], float(target_bid))
